package com.aiquant.identity;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.time.Instant;
import java.util.*;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/auth/manage")
class AdministrationController {
    final Accounts a;
    AdministrationController(Accounts accounts){a=accounts;}
    record Page(List<Map<String,Object>> items,long total,int page,int size){}
    record TenantEdit(@NotBlank @Size(max=80) String name,boolean enabled){}
    record TenantCreate(@NotBlank @Size(max=80) String name,@NotNull UUID ownerId){}
    record UserCreate(@NotBlank @Size(max=32) String username,@Size(max=80) String displayName,@Size(max=254) String email){}
    record UserEdit(@NotNull @Size(max=80) String displayName,boolean enabled){}
    record PlatformGrant(boolean enabled){}
    record RoleEdit(@NotBlank @Size(max=80) String name,@NotNull @Size(max=400) String description,@NotNull @Size(max=30) Set<String> permissions,boolean enabled,@Min(0) long version){}
    record Grant(UUID userId,@Size(max=254) String identifier,@NotNull @Pattern(regexp="OWNER|ADMIN|MEMBER|VIEWER") String role,@NotNull @Size(max=200) Set<UUID> customRoles){}
    record MenuEdit(UUID parentId,@NotBlank @Size(max=80) String label,@Size(max=100) String path,@NotNull @Size(max=80) String permission,@Min(-10000) @Max(10000) int sortOrder,boolean enabled,@Min(0) long version){}
    Accounts.Principal manager(HttpServletRequest req,boolean write){var p=a.require(req,write,false);if(!p.platformAdmin())a.tenantAdmin(p);return p;}
    UUID scope(Accounts.Principal p,UUID target){UUID id=target==null?p.tenant():target;if(!p.platformAdmin()&&!id.equals(p.tenant()))throw Accounts.fail(HttpStatus.FORBIDDEN,"不能管理其他租户。");if(a.db.queryForObject("select count(*) from identity.tenant where id=?",Integer.class,id)==0)throw Accounts.fail(HttpStatus.NOT_FOUND,"租户不存在。");return id;}
    void platform(Accounts.Principal p){a.admin(p);}
    String json(Object value){try{return a.mapper.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException(e);}}
    void audit(Accounts.Principal p,UUID tenant,String action,String target,Object before,Object after){a.db.update("insert into identity.audit(user_id,tenant_id,action,target,before_state,after_state) values(?,?,?,?,?::jsonb,?::jsonb)",p.user(),tenant,action,target,json(before),json(after));}
    Map<String,Object> user(UUID id){var rows=a.db.queryForList("select id,username,display_name as \"displayName\",email,enabled,verified,must_change as \"mustChangePassword\",platform_admin as \"platformAdmin\" from identity.account where id=?",id);if(rows.isEmpty())throw Accounts.fail(HttpStatus.NOT_FOUND,"用户不存在。");return rows.get(0);}
    Map<String,Object> role(UUID tenant,UUID id){var rows=a.db.queryForList("select id,name,description,permissions,enabled,version from identity.access_role where id=? and tenant_id=?",id,tenant);if(rows.isEmpty())throw Accounts.fail(HttpStatus.NOT_FOUND,"角色不存在于当前租户。");return rows.get(0);}
    Map<String,Object> tenant(UUID id){var rows=a.db.queryForList("select id,name,enabled from identity.tenant where id=?",id);if(rows.isEmpty())throw Accounts.fail(HttpStatus.NOT_FOUND,"租户不存在。");return rows.get(0);}
    Page page(String select,String from,List<Object> args,int page,int size){if(page<1||size<1||size>100)throw Accounts.fail(HttpStatus.BAD_REQUEST,"页码至少 1，每页最多 100 条。");long count=a.db.queryForObject("select count(*) "+from,Long.class,args.toArray());var params=new ArrayList<>(args);params.add(size);params.add((long)(page-1)*size);return new Page(a.db.queryForList(select+" "+from+" order by x.created_at desc,x.id desc limit ? offset ?",params.toArray()),count,page,size);}
    @GetMapping("/catalog") Object catalog(HttpServletRequest req){var p=manager(req,false);return Map.of("platformAdmin",p.platformAdmin(),"permissions",AccessControl.MODULES.entrySet().stream().map(e->Map.of("module",e.getKey(),"label",e.getValue(),"read",e.getKey()+".read","write",e.getKey()+".write")).toList(),"routes",AccessControl.ROUTES.keySet().stream().sorted().toList());}
    @GetMapping("/tenants") Object tenants(HttpServletRequest req,@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="20") int size){var p=manager(req,false);var args=new ArrayList<Object>();String from="from identity.tenant x where lower(x.name) like ?";args.add("%"+q.toLowerCase(Locale.ROOT)+"%");if(!p.platformAdmin()){from+=" and x.id=?";args.add(p.tenant());}return page("select x.id,x.name,x.enabled,x.created_at as \"createdAt\",(select count(*) from identity.membership m where m.tenant_id=x.id) as members",from,args,page,size);}
    @PostMapping("/tenants") Object createTenant(HttpServletRequest req,@Valid @RequestBody TenantCreate body){var p=manager(req,true);platform(p);var u=a.account(body.ownerId());if(!Boolean.TRUE.equals(u.get("verified"))||!Boolean.TRUE.equals(u.get("enabled")))throw Accounts.fail(HttpStatus.BAD_REQUEST,"所有者须为可登录的启用账号。");return a.tx.execute(status->{UUID id=a.createTenant(body.ownerId(),body.name());audit(p,id,"TENANT_CREATE_ADMIN",id.toString(),null,tenant(id));return Map.of("id",id);});}
    @PostMapping("/tenants/{id}") Object editTenant(HttpServletRequest req,@PathVariable UUID id,@Valid @RequestBody TenantEdit body){var p=manager(req,true);scope(p,id);platform(p);if(!body.enabled()&&id.equals(Accounts.LEGACY))throw Accounts.fail(HttpStatus.CONFLICT,"默认租户不能停用。");return a.tx.execute(status->{var before=tenant(id);a.db.update("update identity.tenant set name=?,enabled=? where id=?",body.name().strip(),body.enabled(),id);if(!body.enabled()){a.db.update("delete from identity.session where tenant_id=?",id);a.db.update("delete from identity.api_key where tenant_id=?",id);}audit(p,id,"TENANT_UPDATE",id.toString(),before,tenant(id));return Map.of("message","租户已更新。");});}
    @GetMapping("/users") Object users(HttpServletRequest req,@RequestParam(required=false) UUID tenantId,@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="20") int size){var p=manager(req,false);UUID target=scope(p,tenantId);String from="from identity.account x where (lower(x.username) like ? or lower(coalesce(x.email,'')) like ? or lower(x.display_name) like ?)";String search="%"+q.toLowerCase(Locale.ROOT)+"%";var args=new ArrayList<Object>(List.of(search,search,search));if(!p.platformAdmin()){from+=" and exists(select 1 from identity.membership m where m.user_id=x.id and m.tenant_id=?)";args.add(target);}return page("select x.id,x.username,x.display_name as \"displayName\",x.email,x.verified,x.enabled,x.platform_admin as \"platformAdmin\",x.must_change as \"mustChangePassword\",x.created_at as \"createdAt\"",from,args,page,size);}
    @PostMapping("/users") Object createUser(HttpServletRequest req,@RequestParam(required=false) UUID tenantId,@Valid @RequestBody UserCreate body){var p=manager(req,true);platform(p);UUID target=scope(p,tenantId);String name=Accounts.username(body.username());return a.tx.execute(status->{UUID id;if(body.email()!=null&&!body.email().isBlank()){a.register(name,body.email());id=a.db.queryForObject("select id from identity.account where username=?",UUID.class,name);}else{id=UUID.randomUUID();a.db.update("insert into identity.account(id,username,password_hash,verified,must_change) values(?,?,?,true,true)",id,name,a.passwords.encode(name+"123456"));}a.db.update("update identity.account set display_name=? where id=?",body.displayName()==null?"":body.displayName().strip(),id);a.db.update("insert into identity.membership(tenant_id,user_id,role) values(?,?,'MEMBER')",target,id);audit(p,target,"ACCOUNT_PROVISION",id.toString(),null,user(id));return Map.of("id",id,"message",body.email()==null||body.email().isBlank()?"账号已创建，首次登录需改密；邮箱可由用户自行验证绑定。":"账号已创建并发送验证邮件，邮箱验证后方可登录。");});}
    @PostMapping("/users/{id}") Object editUser(HttpServletRequest req,@PathVariable UUID id,@Valid @RequestBody UserEdit body){var p=manager(req,true);platform(p);return a.tx.execute(status->{var before=user(id);if((p.user().equals(id)||Boolean.TRUE.equals(before.get("platformAdmin")))&&!body.enabled())throw Accounts.fail(HttpStatus.CONFLICT,"不能停用当前账号或平台管理员。");a.db.update("update identity.account set display_name=?,enabled=? where id=?",body.displayName().strip(),body.enabled(),id);if(!body.enabled())a.revokeAll(id);audit(p,p.tenant(),"ACCOUNT_UPDATE",id.toString(),before,user(id));return Map.of("message","用户已更新。");});}
    @PostMapping("/users/{id}/platform") Object platformRole(HttpServletRequest req,@PathVariable UUID id,@RequestBody PlatformGrant body){var p=manager(req,true);platform(p);if(p.user().equals(id))throw Accounts.fail(HttpStatus.CONFLICT,"不能修改自己的平台管理员身份。");return a.tx.execute(status->{a.db.execute("select pg_advisory_xact_lock(71203003)");var before=user(id);if(!Boolean.TRUE.equals(before.get("enabled"))||!Boolean.TRUE.equals(before.get("verified")))throw Accounts.fail(HttpStatus.CONFLICT,"平台管理员须为已启用、可登录的账号。");a.db.update("update identity.account set platform_admin=? where id=?",body.enabled(),id);a.revokeAll(id);audit(p,p.tenant(),"PLATFORM_GRANT",id.toString(),before,user(id));return Map.of("message","平台身份已变更，原会话和密钥已撤销。");});}
    @GetMapping("/members") Object members(HttpServletRequest req,@RequestParam(required=false) UUID tenantId){var p=manager(req,false);UUID target=scope(p,tenantId);return a.db.queryForList("select u.id,u.username,u.display_name as \"displayName\",u.email,m.role,coalesce((select jsonb_agg(x.role_id) from identity.role_assignment x where x.user_id=u.id and x.tenant_id=m.tenant_id),'[]'::jsonb) as \"customRoles\" from identity.membership m join identity.account u on u.id=m.user_id where m.tenant_id=? order by u.username",target);}
    @PostMapping("/grants") Object grant(HttpServletRequest req,@RequestParam(required=false) UUID tenantId,@Valid @RequestBody Grant body){var p=manager(req,true);UUID target=scope(p,tenantId);if(!p.platformAdmin()&&!p.role().equals("OWNER"))throw Accounts.fail(HttpStatus.FORBIDDEN,"仅租户所有者或平台管理员可以分配角色。");UUID selectedUser=body.userId();if(selectedUser==null){String name=body.identifier()==null?"":body.identifier().strip().toLowerCase(Locale.ROOT);var found=a.db.queryForList("select id from identity.account where username=? or email=?",name,name);if(found.isEmpty())throw Accounts.fail(HttpStatus.NOT_FOUND,"账号不存在，请先完成注册。");selectedUser=(UUID)found.get(0).get("id");}UUID userId=selectedUser;return a.tx.execute(status->{a.db.queryForObject("select id from identity.tenant where id=? for update",UUID.class,target);for(UUID id:body.customRoles())role(target,id);var before=a.db.queryForList("select m.role,(select jsonb_agg(x.role_id) from identity.role_assignment x where x.tenant_id=m.tenant_id and x.user_id=m.user_id) as roles from identity.membership m where m.tenant_id=? and m.user_id=?",target,userId);var authority=new Accounts.Principal(p.user(),target,p.credential(),p.username(),"OWNER",p.platformAdmin(),false,false,"READ_WRITE");a.member(authority,userId,body.role(),false);a.db.update("delete from identity.role_assignment where tenant_id=? and user_id=?",target,userId);for(UUID id:body.customRoles())a.db.update("insert into identity.role_assignment(tenant_id,user_id,role_id) values(?,?,?)",target,userId,id);audit(p,target,"ROLE_ASSIGN",userId.toString(),before,Map.of("role",body.role(),"customRoles",body.customRoles()));return Map.of("message","授权已更新，新请求立即使用最新权限。");});}
    @PostMapping("/members/{id}/remove") Object removeMember(HttpServletRequest req,@PathVariable UUID id,@RequestParam(required=false) UUID tenantId){var p=manager(req,true);UUID target=scope(p,tenantId);var authority=p.platformAdmin()?new Accounts.Principal(p.user(),target,p.credential(),p.username(),"OWNER",true,false,false,"READ_WRITE"):p;a.member(authority,id,"MEMBER",true);return Map.of("message","成员已移除，租户会话与密钥已撤销。");}
    @GetMapping("/roles") Object roles(HttpServletRequest req,@RequestParam(required=false) UUID tenantId){var p=manager(req,false);UUID target=scope(p,tenantId);return a.db.queryForList("select id,name,description,permissions,enabled,version,(select count(*) from identity.role_assignment x where x.role_id=r.id) as assignments from identity.access_role r where tenant_id=? order by created_at,id",target);}
    @GetMapping("/effective") Object effective(HttpServletRequest req,@RequestParam UUID userId,@RequestParam(required=false) UUID tenantId){var p=manager(req,false);UUID target=scope(p,tenantId);var rows=a.db.queryForList("select m.role,u.username,u.platform_admin from identity.membership m join identity.account u on u.id=m.user_id where m.tenant_id=? and m.user_id=?",target,userId);if(rows.isEmpty())throw Accounts.fail(HttpStatus.NOT_FOUND,"用户不属于当前租户。");var row=rows.get(0);var selected=new Accounts.Principal(userId,target,p.credential(),(String)row.get("username"),(String)row.get("role"),Boolean.TRUE.equals(row.get("platform_admin")),false,false,"READ_WRITE");return Map.of("permissions",a.access.effective(selected),"menus",a.access.navigation(selected),"role",selected.role(),"platformAdmin",selected.platformAdmin());}
    @PostMapping("/roles") Object createRole(HttpServletRequest req,@RequestParam(required=false) UUID tenantId,@Valid @RequestBody RoleEdit body){var p=manager(req,true);UUID target=scope(p,tenantId);AccessControl.validate(body.permissions());return a.tx.execute(status->{a.db.queryForObject("select id from identity.tenant where id=? for update",UUID.class,target);if(a.db.queryForObject("select count(*) from identity.access_role where tenant_id=?",Integer.class,target)>=200)throw Accounts.fail(HttpStatus.CONFLICT,"每个租户最多 200 个自定义角色。");UUID id=UUID.randomUUID();a.db.update("insert into identity.access_role(id,tenant_id,name,description,permissions,enabled) values(?,?,?,?,?::jsonb,?)",id,target,body.name().strip(),body.description().strip(),json(body.permissions()),body.enabled());audit(p,target,"ROLE_CREATE",id.toString(),null,Map.of("name",body.name(),"permissions",body.permissions(),"enabled",body.enabled()));return Map.of("id",id);});}
    @PostMapping("/roles/{id}") Object editRole(HttpServletRequest req,@PathVariable UUID id,@RequestParam(required=false) UUID tenantId,@Valid @RequestBody RoleEdit body){var p=manager(req,true);UUID target=scope(p,tenantId);AccessControl.validate(body.permissions());return a.tx.execute(status->{var before=role(target,id);int changed=a.db.update("update identity.access_role set name=?,description=?,permissions=?::jsonb,enabled=?,version=version+1 where id=? and tenant_id=? and version=?",body.name().strip(),body.description().strip(),json(body.permissions()),body.enabled(),id,target,body.version());if(changed!=1)throw Accounts.fail(HttpStatus.CONFLICT,"角色已被其他人修改，请刷新后重试。");audit(p,target,"ROLE_UPDATE",id.toString(),before,Map.of("name",body.name(),"permissions",body.permissions(),"enabled",body.enabled()));return Map.of("message","角色已更新。");});}
@PostMapping("/roles/{id}/delete") Object deleteRole(HttpServletRequest req,@PathVariable UUID id,@RequestParam(required=false) UUID tenantId){var p=manager(req,true);UUID target=scope(p,tenantId);return a.tx.execute(status->{a.db.queryForObject("select id from identity.tenant where id=? for update",UUID.class,target);var before=role(target,id);if(a.db.queryForObject("select count(*) from identity.role_assignment where role_id=? and tenant_id=?",Integer.class,id,target)>0)throw Accounts.fail(HttpStatus.CONFLICT,"角色仍有用户，请先撤销分配，或停用角色。");a.db.update("delete from identity.access_role where id=? and tenant_id=?",id,target);audit(p,target,"ROLE_DELETE",id.toString(),before,null);return Map.of("message","角色已删除。");});}
    @GetMapping("/menus") Object menus(HttpServletRequest req){var p=manager(req,false);platform(p);return a.db.queryForList("select id,parent_id as \"parentId\",label,path,permission,sort_order as \"sortOrder\",enabled,version from identity.menu order by sort_order,id");}
void menuValidate(UUID id,MenuEdit body){if(body.path()==null){if(!body.permission().isEmpty())throw Accounts.fail(HttpStatus.BAD_REQUEST,"分组菜单不设置功能权限。");}else if(!AccessControl.ROUTES.containsKey(body.path())||!body.permission().equals(AccessControl.ROUTES.get(body.path())+".read"))throw Accounts.fail(HttpStatus.BAD_REQUEST,"菜单只能指向已存在的系统路由和对应读权限。");if(body.parentId()!=null){if(a.db.queryForObject("select count(*) from identity.menu where id=?",Integer.class,body.parentId())==0)throw Accounts.fail(HttpStatus.BAD_REQUEST,"上级菜单不存在。");if(id!=null&&a.db.queryForObject("with recursive p as(select id,parent_id from identity.menu where id=? union all select m.id,m.parent_id from identity.menu m join p on m.id=p.parent_id) select count(*) from p where id=?",Integer.class,body.parentId(),id)>0)throw Accounts.fail(HttpStatus.BAD_REQUEST,"菜单层级不能形成循环。");}}
    @PostMapping("/menus") Object createMenu(HttpServletRequest req,@Valid @RequestBody MenuEdit body){var p=manager(req,true);platform(p);return a.tx.execute(status->{a.db.execute("select pg_advisory_xact_lock(71203004)");menuValidate(null,body);UUID id=UUID.randomUUID();a.db.update("insert into identity.menu(id,parent_id,label,path,permission,sort_order,enabled) values(?,?,?,?,?,?,?)",id,body.parentId(),body.label().strip(),body.path(),body.permission(),body.sortOrder(),body.enabled());audit(p,null,"MENU_CREATE",id.toString(),null,body);return Map.of("id",id);});}
    @PostMapping("/menus/{id}") Object editMenu(HttpServletRequest req,@PathVariable UUID id,@Valid @RequestBody MenuEdit body){var p=manager(req,true);platform(p);return a.tx.execute(status->{a.db.execute("select pg_advisory_xact_lock(71203004)");menuValidate(id,body);var before=a.db.queryForList("select id,parent_id,label,path,permission,sort_order,enabled,version from identity.menu where id=?",id);if(a.db.update("update identity.menu set parent_id=?,label=?,path=?,permission=?,sort_order=?,enabled=?,version=version+1 where id=? and version=?",body.parentId(),body.label().strip(),body.path(),body.permission(),body.sortOrder(),body.enabled(),id,body.version())!=1)throw Accounts.fail(HttpStatus.CONFLICT,"菜单不存在或已被修改，请刷新后重试。");audit(p,null,"MENU_UPDATE",id.toString(),before,body);return Map.of("message","菜单已更新，重新加载主系统后生效。");});}
    @PostMapping("/menus/{id}/delete") Object deleteMenu(HttpServletRequest req,@PathVariable UUID id){var p=manager(req,true);platform(p);return a.tx.execute(status->{a.db.execute("select pg_advisory_xact_lock(71203004)");if(a.db.queryForObject("select count(*) from identity.menu where parent_id=?",Integer.class,id)>0)throw Accounts.fail(HttpStatus.CONFLICT,"请先处理下级菜单。");var before=a.db.queryForList("select id,label,path,permission from identity.menu where id=?",id);if(before.isEmpty())throw Accounts.fail(HttpStatus.NOT_FOUND,"菜单不存在。");a.db.update("delete from identity.menu where id=?",id);audit(p,null,"MENU_DELETE",id.toString(),before,null);return Map.of("message","菜单已删除；API 权限不随菜单隐藏而改变。");});}
    @GetMapping("/sessions") Object sessions(HttpServletRequest req,@RequestParam UUID userId,@RequestParam(required=false) UUID tenantId){var p=manager(req,false);UUID target=scope(p,tenantId);if(!p.platformAdmin()&&a.db.queryForObject("select count(*) from identity.membership where user_id=? and tenant_id=?",Integer.class,userId,target)==0)throw Accounts.fail(HttpStatus.NOT_FOUND,"用户不属于当前租户。");return a.db.queryForList("select id,tenant_id as \"tenantId\",created_at as \"createdAt\",expires_at as \"expiresAt\" from identity.session where user_id=? and expires_at>now()"+(p.platformAdmin()?"":" and tenant_id=?")+" order by created_at desc",p.platformAdmin()?new Object[]{userId}:new Object[]{userId,target});}
    @PostMapping("/sessions/{id}/revoke") Object revokeSession(HttpServletRequest req,@PathVariable UUID id,@RequestParam(required=false) UUID tenantId){var p=manager(req,true);UUID target=scope(p,tenantId);return a.tx.execute(status->{int changed=a.db.update("delete from identity.session where id=?"+(p.platformAdmin()?"":" and tenant_id=?"),p.platformAdmin()?new Object[]{id}:new Object[]{id,target});if(changed==0)throw Accounts.fail(HttpStatus.NOT_FOUND,"会话不存在于可管理范围。");audit(p,target,"ADMIN_SESSION_REVOKE",id.toString(),null,null);return Map.of("message","会话已撤销。");});}
    @GetMapping("/keys") Object keys(HttpServletRequest req,@RequestParam(required=false) UUID tenantId){var p=manager(req,false);UUID target=scope(p,tenantId);return a.db.queryForList("select k.id,k.name,k.scope,k.user_id as \"userId\",u.username,k.expires_at as \"expiresAt\" from identity.api_key k join identity.account u on u.id=k.user_id where k.tenant_id=? order by k.created_at desc limit 500",target);}
    @PostMapping("/keys/{id}/revoke") Object revokeKey(HttpServletRequest req,@PathVariable UUID id,@RequestParam(required=false) UUID tenantId){var p=manager(req,true);UUID target=scope(p,tenantId);return a.tx.execute(status->{if(a.db.update("delete from identity.api_key where id=? and tenant_id=?",id,target)==0)throw Accounts.fail(HttpStatus.NOT_FOUND,"密钥不存在于当前租户。");audit(p,target,"ADMIN_KEY_REVOKE",id.toString(),null,null);return Map.of("message","密钥已撤销。");});}
    @GetMapping("/history") Object history(HttpServletRequest req,@RequestParam(required=false) UUID tenantId,@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="20") int size){var p=manager(req,false);UUID target=scope(p,tenantId);var args=new ArrayList<Object>();String from="from identity.audit x left join identity.account u on u.id=x.user_id where (x.action ilike ? or coalesce(u.username,'') ilike ? or coalesce(x.target,'') ilike ?)";String pattern="%"+q+"%";args.addAll(List.of(pattern,pattern,pattern));if(!p.platformAdmin()||tenantId!=null){from+=" and x.tenant_id=?";args.add(target);}return page("select x.id,x.user_id as \"userId\",u.username,x.tenant_id as \"tenantId\",x.action,x.target,x.before_state as \"beforeState\",x.after_state as \"afterState\",x.created_at as \"createdAt\"",from,args,page,size);}
    @GetMapping("/operations") Object operations(HttpServletRequest req,@RequestParam(required=false) UUID tenantId,@RequestParam(defaultValue="") String q,@RequestParam(required=false) Integer status,@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="20") int size){var p=manager(req,false);UUID target=scope(p,tenantId);var args=new ArrayList<Object>();String from="from identity.operation_log x left join identity.account u on u.id=x.user_id where (x.path ilike ? or coalesce(u.username,'') ilike ? or coalesce(x.trace_id,'') ilike ?)";String pattern="%"+q+"%";args.addAll(List.of(pattern,pattern,pattern));if(!p.platformAdmin()||tenantId!=null){from+=" and x.tenant_id=?";args.add(target);}if(status!=null){from+=" and x.status=?";args.add(status);}return page("select x.id,u.username,x.user_id as \"userId\",x.tenant_id as \"tenantId\",x.method,x.path,x.status,x.duration_ms as \"durationMs\",x.trace_id as \"traceId\",x.created_at as \"createdAt\"",from,args,page,size);}
}
